#include <stdio.h>

void hit(int *health, int dmg)
{
    *health -= dmg;
    if (*health < 0) *health = 0;
}

int main(void)
{
    int h = 50;
    int *p = &h;
    printf("h is %d, *p is %d\n", h, *p);
    *p = 45;
    printf("after *p = 45, h is %d\n", h);
    hit(&h, 10);
    printf("after hit(&h, 10), h is %d\n", h);
    return 0;
}

